			dir := t.TempDir()
			var raw []byte
			raw = append(raw, logMagic...)
			raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
			raw = append(raw, encodeFrame(mustMarshal(e))...)
