1	package relayproof
2	
3	import (
4		"errors"
5		"testing"
6	)
7	
8	// These tests pin the queue-level identity rule behind the CLI regression
9	// tests: re-using a non-terminal message id is idempotent only when the ENTIRE
10	// envelope content is identical — source chain, destination chain, nonce,
11	// payload, proof height and absolute expiry. Identity is never judged by id
12	// alone or by the (source, destination, nonce) replay triple alone. A rejected
13	// resubmit must persist nothing, and the returned existing record must match
14	// what Query/Queries report.
15	
16	func fullEnvelope(id string) Envelope {
17		return Envelope{
18			Message: Message{
19				ID:      id,
20				From:    "chain-a",
21				To:      "chain-b",
22				Nonce:   7,
23				Payload: "hello",
24				ProofAt: 90,
25			},
26			ExpiresAt: 9_000_000_000_000,
27		}
28	}
29	
30	// Changing any single content field of a pending id is ErrConflict; the
31	// original record keeps every field, its pending state and its submission
32	// position, nothing new is persisted, and an identical resubmit afterwards
33	// still returns the original.
34	func TestSubmitConflictForEverySingleContentField(t *testing.T) {
35		base := fullEnvelope("m")
36		cases := []struct {
37			name   string
38			mutate func(Envelope) Envelope
39		}{
40			{"source chain", func(e Envelope) Envelope { e.Message.From = "chain-other"; return e }},
41			{"destination chain", func(e Envelope) Envelope { e.Message.To = "chain-c"; return e }},
42			{"nonce", func(e Envelope) Envelope { e.Message.Nonce = 8; return e }},
43			{"payload", func(e Envelope) Envelope { e.Message.Payload = "HELLO"; return e }},
44			{"proof height", func(e Envelope) Envelope { e.Message.ProofAt = 91; return e }},
45			{"absolute expiry", func(e Envelope) Envelope { e.ExpiresAt = 9_000_000_000_001; return e }},
46			// Explicit zero values are real content too: turning the expiry off
47			// after a finite expiry was stored must conflict.
48			{"expiry to never", func(e Envelope) Envelope { e.ExpiresAt = 0; return e }},
49			{"payload to empty", func(e Envelope) Envelope { e.Message.Payload = ""; return e }},
50		}
51		for _, tc := range cases {
52			t.Run(tc.name, func(t *testing.T) {
53				q, _ := openTempQueue(t)
54				defer q.Close()
55	
56				first, err := q.Submit(base)
57				if err != nil {
58					t.Fatal(err)
59				}
60				changed := tc.mutate(base)
61				if _, err := q.Submit(changed); !errors.Is(err, ErrConflict) {
62					t.Fatalf("want ErrConflict, got %v", err)
63				}
64	
65				if len(q.records) != 1 || len(q.order) != 1 || q.order[0] != "m" || q.nextSeq != 1 {
66					t.Fatalf("rejected submit must persist nothing: records=%d order=%v nextSeq=%d",
67						len(q.records), q.order, q.nextSeq)
68				}
69				got := statusOf(t, q, "m")
70				if got.Msg != base {
71					t.Fatalf("original content overwritten:\nwant %+v\ngot  %+v", base, got.Msg)
72				}
73				if got.Status != StatusPending || got.Reason != "awaiting first processing" ||
74					got.Attempts != 0 || got.NextRetry != 0 {
75					t.Fatalf("pending state changed on conflict: %+v", got)
76				}
77	
78				// The rejected submit must not have consumed a seq: a later new
79				// message still takes seq 1, and an identical resubmit still works.
80				if again, err := q.Submit(base); err != nil || again.Seq != first.Seq {
81					t.Fatalf("identical resubmit after rejected submit must return original (seq %d): rec=%+v err=%v",
82						first.Seq, again, err)
83				}
84				later := fullEnvelope("n")
85				rec, err := q.Submit(later)
86				if err != nil {
87					t.Fatal(err)
88				}
89				if rec.Seq != 1 {
90					t.Fatalf("rejected submit must not consume a seq number: got %d", rec.Seq)
91				}
92			})
93		}
94	}
95	
96	// Content identity must not collapse to the replay triple: same id and same
97	// (from, to, nonce) but different payload, proof height or expiry is still a
98	// conflict, in both comparison directions.
99	func TestSubmitConflictNotJudgedByIdOrNonceOnly(t *testing.T) {
100		q, _ := openTempQueue(t)
101		defer q.Close()
102	
103		first := fullEnvelope("m")
104		if _, err := q.Submit(first); err != nil {
105			t.Fatal(err)
106		}
107		second := first
108		second.Message.Payload = "different"
109		second.Message.ProofAt = 91
110		second.ExpiresAt = 1
111		if _, err := q.Submit(second); !errors.Is(err, ErrConflict) {
112			t.Fatalf("same id/nonce triple but different content must conflict: %v", err)
113		}
114		// And the reverse ordering of the two contents must give the same verdict.
115		if _, err := q.Submit(first); err != nil {
116			t.Fatalf("original content must still resubmit idempotently after rejection: %v", err)
117		}
118	}
119	
120	// A successful idempotent resubmit on a pending record returns a value equal to
121	// the first submit echo and to what Query reports; Queries still lists the id
122	// exactly once with its original seq, including across a reopen.
123	func TestSubmitIdenticalPendingEchoMatchesQueryAndSurvivesReopen(t *testing.T) {
124		dir := t.TempDir()
125		q, err := Open(dir)
126		if err != nil {
127			t.Fatal(err)
128		}
129		want := fullEnvelope("m")
130		first, err := q.Submit(want)
131		if err != nil {
132			t.Fatal(err)
133		}
134		again, err := q.Submit(want)
135		if err != nil {
136			t.Fatalf("identical pending resubmit: %v", err)
137		}
138		if *again != *first {
139			t.Fatalf("resubmit echo differs from first submit:\nfirst=%+v\nagain=%+v", first, again)
140		}
141		qy, ok := q.Query("m")
142		if !ok {
143			t.Fatal("missing m")
144		}
145		if qy.ID != want.Message.ID || qy.From != want.Message.From || qy.To != want.Message.To ||
146			qy.Nonce != want.Message.Nonce || qy.Payload != want.Message.Payload ||
147			qy.ProofAt != want.Message.ProofAt || qy.ExpiresAt != want.ExpiresAt ||
148			qy.Status != StatusPending || qy.Attempts != 0 || qy.NextRetry != 0 {
149			t.Fatalf("query disagrees with resubmit echo: %+v echo=%+v", qy, again)
150		}
151		if all := q.Queries(); len(all) != 1 || all[0].ID != "m" {
152			t.Fatalf("listing must contain the id exactly once: %+v", all)
153		}
154		if err := q.Close(); err != nil {
155			t.Fatal(err)
156		}
157	
158		q2, err := Open(dir)
159		if err != nil {
160			t.Fatal(err)
161		}
162		defer q2.Close()
163		if _, err := q2.Submit(want); err != nil {
164			t.Fatalf("identical resubmit after reopen must still be idempotent: %v", err)
165		}
166		if all := q2.Queries(); len(all) != 1 || all[0].ID != "m" || all[0].Payload != want.Message.Payload {
167			t.Fatalf("duplicate persisted across reopen: %+v", all)
168		}
169	}
170	
171	// While waiting, an identical resubmit returns the CURRENT waiting record —
172	// status, reason, attempts and next retry time all populated — equal to the
173	// single Query view; it neither processes early nor reschedules. The message
174	// later delivers exactly on its original schedule.
175	func TestSubmitIdenticalWaitingReturnsCurrentRecord(t *testing.T) {
176		q, _ := openTempQueue(t)
177		defer q.Close()
178		q.RegisterSource("chain-a")
179		q.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true})
