package relayproof

import (
	"bytes"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// Message payloads are arbitrary byte strings compared byte for byte in the
// same-id content check. The Go submit interface never requires a payload to
// be valid UTF-8: it may be empty, plain text, hold NUL bytes or stray
// 0xFF/0xFE bytes, or mix text with them. Such a payload must survive the
// submit echo, single and full queries, an identical resubmit, reopen and log
// compaction exactly — JSON string encoding would otherwise silently rewrite
// the invalid bytes to U+FFFD, so a byte-identical resubmit of an
// unterminated message would wrongly conflict after a reopen.

const replacementCharPayload = "�"

// payloadEnvelope builds a non-terminal envelope carrying payload as id.
func payloadEnvelope(id, payload string) Envelope {
	return Envelope{
		Message: Message{
			ID:      id,
			From:    "chain-a",
			To:      "chain-b",
			Nonce:   uint64(strings.Count(id, "x") + 1),
			Payload: payload,
			ProofAt: 90,
		},
	}
}

// Every payload shape must come back byte-identical from the submit echo, a
// single Query and the full Queries listing.
func TestPayloadArbitraryBytesPreservedInInstance(t *testing.T) {
	q, _ := openTempQueue(t)
	defer q.Close()

	payloads := map[string]string{
		"empty":       "",
		"plain":       "hello",
		"nul":         "a\x00b\x00",
		"ff":          string([]byte{0xFF}),
		"fe":          string([]byte{0xFE}),
		"fffe":        string([]byte{0xFF, 0xFE}),
		"mixed":       "pre\x00mid" + string([]byte{0xFF, 0xFE}) + "post",
		"replacement": replacementCharPayload,
	}
	order := []string{"empty", "plain", "nul", "ff", "fe", "fffe", "mixed", "replacement"}
	for _, name := range order {
		if _, err := q.Submit(payloadEnvelope(name, payloads[name])); err != nil {
			t.Fatalf("submit %s: %v", name, err)
		}
	}

	for _, name := range order {
		want := payloads[name]
		qy, ok := q.Query(name)
		if !ok {
			t.Fatalf("missing %s", name)
		}
		if qy.Payload != want || !bytes.Equal([]byte(qy.Payload), []byte(want)) {
			t.Fatalf("Query payload for %s changed:\nwant % x\ngot  % x", name, want, qy.Payload)
		}
		// An identical resubmit of an unterminated message returns the existing
		// record byte-for-byte and adds nothing.
		echo, err := q.Submit(payloadEnvelope(name, want))
		if err != nil {
			t.Fatalf("identical resubmit %s: %v", name, err)
		}
		if echo.Msg.Message.Payload != want {
			t.Fatalf("resubmit echo payload for %s changed", name)
		}
	}
	all := q.Queries()
	if len(all) != len(order) {
		t.Fatalf("identical resubmits must not add records: got %d rows", len(all))
	}
	for i, qy := range all {
		if qy.ID != order[i] || qy.Payload != payloads[order[i]] {
			t.Fatalf("Queries[%d] = (%s, % x), want (%s, % x)",
				i, qy.ID, qy.Payload, order[i], payloads[order[i]])
		}
	}
}

// 0xFF, 0xFE and the legal character U+FFFD are three different payloads: an
// identical-byte resubmit is the existing record, while changing any single
// byte — or submitting the visually similar replacement character — is a
// content conflict that leaves the original record untouched. The same holds
// after close/reopen, after a forced compaction plus reopen, and after an
// automatic threshold compaction plus reopen.
func TestPayloadInvalidBytesDistinctAcrossPersistenceBoundaries(t *testing.T) {
	payFF := string([]byte{0xFF})
	payFE := string([]byte{0xFE})
	payMixed := "pre" + string([]byte{0xFF}) + "post"

	check := func(t *testing.T, q *Queue) {
		t.Helper()
		// Byte-identical resubmits stay idempotent and add no record.
		before := len(q.Queries())
		for _, p := range []string{payFF, payFE, payMixed, replacementCharPayload} {
			if _, err := q.Submit(payloadEnvelope("ff", payFF)); err != nil {
				// (id fixed below per case)
			}
		}
		for id, want := range map[string]string{"ff": payFF, "fe": payFE, "mixed": payMixed, "ufffd": replacementCharPayload} {
			echo, err := q.Submit(payloadEnvelope(id, want))
			if err != nil {
				t.Fatalf("identical resubmit %s: %v", id, err)
			}
			if echo.Msg.Message.Payload != want || echo.Status != StatusPending {
				t.Fatalf("resubmit %s changed record: %+v", id, echo)
			}
		}
		if len(q.Queries()) != before {
			t.Fatalf("identical resubmits must not add records: %d -> %d", before, len(q.Queries()))
		}

		// One-byte changes and the look-alike legal character all conflict.
		conflicts := []struct {
			id  string
			bad string
		}{
			{"ff", payFE},
			{"ff", replacementCharPayload},
			{"fe", payFF},
			{"fe", replacementCharPayload},
			{"mixed", replacementCharPayload},
			{"ufffd", payFF},
			{"ufffd", payFE},
		}
		for _, c := range conflicts {
			if _, err := q.Submit(payloadEnvelope(c.id, c.bad)); !errors.Is(err, ErrConflict) {
				t.Fatalf("payload %x resubmitted to %q must conflict: %v", c.bad, c.id, err)
			}
		}

		// Originals are untouched.
		want := map[string]string{"ff": payFF, "fe": payFE, "mixed": payMixed, "ufffd": replacementCharPayload}
		for id, p := range want {
			qy, ok := q.Query(id)
			if !ok || qy.Payload != p {
				t.Fatalf("original payload for %s changed after conflicts: ok=%v got % x want % x", id, ok, qy.Payload, p)
			}
		}
	}

	dir := t.TempDir()
	q, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	for id, p := range map[string]string{"ff": payFF, "fe": payFE, "mixed": payMixed, "ufffd": replacementCharPayload} {
		if _, err := q.Submit(payloadEnvelope(id, p)); err != nil {
			t.Fatalf("submit %s: %v", id, err)
		}
	}
	t.Run("same instance", func(t *testing.T) { check(t, q) })
	if err := q.Close(); err != nil {
		t.Fatal(err)
	}

	q = reopen(t, dir)
	t.Run("after reopen", func(t *testing.T) { check(t, q) })

	// Forced snapshot compaction: terminal and non-terminal payloads alike are
	// rewritten byte-exactly.
	q.RegisterSource("chain-a")
	q.UpsertHeader(Header{Chain: "chain-a", Height: 1, Root: "r", Trusted: true})
	// Turn one record terminal (success); its payload must survive too.
	term := payloadEnvelope("term", "done"+string([]byte{0xFF}))
	term.Message.ProofAt = 1
	if _, err := q.Submit(term); err != nil {
		t.Fatal(err)
	}
	if _, err := q.Advance(1000); err != nil {
		t.Fatal(err)
	}
	if st, _ := q.Query("term"); st.Status != StatusSuccess || st.Payload != term.Message.Payload {
		t.Fatalf("term not delivered: %+v", st)
	}
	if err := q.store.compact(q.snapshot()); err != nil {
		t.Fatalf("compact: %v", err)
	}
	if err := q.Close(); err != nil {
		t.Fatal(err)
	}

	q = reopen(t, dir)
	t.Run("after compaction and reopen", func(t *testing.T) { check(t, q) })
	if st, ok := q.Query("term"); !ok || st.Payload != term.Message.Payload || st.Status != StatusSuccess {
		t.Fatalf("terminal payload lost in compaction: ok=%v %+v", ok, st)
	}
	if err := q.Close(); err != nil {
		t.Fatal(err)
	}

	// The on-disk log stores invalid bytes base64-encoded and never the
	// replacement character.
	raw, err := os.ReadFile(filepath.Join(dir, logName))
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Contains(raw, []byte(`"payloadB64":"`)) {
		t.Fatalf("invalid-UTF-8 payload not stored byte-exactly: %s", raw)
	}
	if bytes.Contains(raw, []byte(replacementCharPayload)) {
		t.Fatalf("log contains U+FFFD where an invalid-byte payload was rewritten: %s", raw)
	}
}

// Valid-UTF-8 payloads — plain text, empty, NUL bytes, U+FFFD itself — keep
// the historical plain "payload" field, so existing state directories, the
// CLI text interface and the README examples stay byte-compatible on disk.
func TestPayloadValidUTF8KeepsHistoricalEncoding(t *testing.T) {
	dir := t.TempDir()
	q, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	for _, p := range []string{"hello", "", "a\x00b", replacementCharPayload} {
		id := "m-" + strings.ReplaceAll(strings.ReplaceAll(p, "\x00", "0"), replacementCharPayload, "r")
		if id == "m-" && p == "" {
			id = "m-empty"
		}
		if _, err := q.Submit(payloadEnvelope(id, p)); err != nil {
			t.Fatalf("submit %q: %v", p, err)
		}
	}
	if err := q.Close(); err != nil {
		t.Fatal(err)
	}

	raw, err := os.ReadFile(filepath.Join(dir, logName))
	if err != nil {
		t.Fatal(err)
	}
	if bytes.Contains(raw, []byte("payloadB64")) {
		t.Fatalf("valid-UTF-8 payloads must keep the plain payload field: %s", raw)
	}
	if !bytes.Contains(raw, []byte(`"payload":"hello"`)) {
		t.Fatalf("plain payload missing from log: %s", raw)
	}

	q = reopen(t, dir)
	defer q.Close()
	echo, err := q.Submit(payloadEnvelope("m-hello", "hello"))
	if err != nil || echo.Msg.Message.Payload != "hello" {
		t.Fatalf("plain payload resubmit after reopen: rec=%+v err=%v", echo, err)
	}
	if _, err := q.Submit(payloadEnvelope("m-hello", string([]byte{0xFF}))); !errors.Is(err, ErrConflict) {
		t.Fatalf("invalid byte 0xFF must differ from every text payload: %v", err)
	}
}

// An unterminated message whose identical resubmit after a reopen must return
// the existing record — including its waiting schedule — rather than a content
// conflict, because the saved payload bytes equal the submitted bytes.
func TestPayloadInvalidBytesWaitingResubmitAfterReopenKeepsSchedule(t *testing.T) {
	pay := "w" + string([]byte{0x00, 0xFF, 0xFE})
	env := payloadEnvelope("w", pay)
	env.Message.ProofAt = 100 // no trusted header covers it -> waiting

	dir := t.TempDir()
	q, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	q.RegisterSource("chain-a")
	if _, err := q.Submit(env); err != nil {
		t.Fatal(err)
	}
	if _, err := q.Advance(1000); err != nil {
		t.Fatal(err)
	}
	st, _ := q.Query("w")
	if st.Status != StatusWaiting || st.Attempts != 1 || st.NextRetry != 2000 {
		t.Fatalf("unexpected pre-reopen state: %+v", st)
	}
	if err := q.Close(); err != nil {
		t.Fatal(err)
	}

	q = reopen(t, dir)
	defer q.Close()
	echo, err := q.Submit(env)
	if err != nil {
		t.Fatalf("byte-identical resubmit after reopen must return existing record: %v", err)
	}
	if echo.Msg.Message.Payload != pay || echo.Status != StatusWaiting ||
		echo.Attempts != 1 || echo.NextRetry != 2000 {
		t.Fatalf("resubmit must not reschedule or rewrite payload: %+v", echo)
	}
	if len(q.Queries()) != 1 {
		t.Fatalf("resubmit must not add a record")
	}
	// One changed byte conflicts, and the waiting schedule is untouched.
	bad := env
	bad.Message.Payload = "w" + string([]byte{0x00, 0xFF, 0x00})
	if _, err := q.Submit(bad); !errors.Is(err, ErrConflict) {
		t.Fatalf("one-byte payload change must conflict: %v", err)
	}
	st2, _ := q.Query("w")
	if st2.Payload != pay || st2.Attempts != 1 || st2.NextRetry != 2000 {
		t.Fatalf("conflicting resubmit changed the record: %+v", st2)
	}
}

// Automatic threshold compaction must carry invalid-UTF-8 payloads — including
// the oversized payload that triggers it — byte-exactly into the snapshot and
// they must read identically after reopen.
func TestPayloadInvalidBytesSurviveAutomaticCompaction(t *testing.T) {
	dir := t.TempDir()
	q, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	small := payloadEnvelope("small", "x"+string([]byte{0xFF}))
	if _, err := q.Submit(small); err != nil {
		t.Fatal(err)
	}

	// A large invalid-UTF-8 payload crosses the compaction threshold inside the
	// Submit call itself.
	filler := payloadEnvelope("filler", strings.Repeat(string([]byte{0xFF}), compactThreshold+4096))
	if _, err := q.Submit(filler); err != nil {
		t.Fatalf("filler submit triggered compaction failure: %v", err)
	}
	if !q.store.needsCompaction() && q.store.size <= compactThreshold {
		// Compaction should already have run (size reset below threshold).
		t.Fatalf("expected compaction to have run, size=%d", q.store.size)
	}
	if q.store.size > compactThreshold {
		t.Fatalf("auto-compaction did not shrink the log: size=%d", q.store.size)
	}
	if err := q.Close(); err != nil {
		t.Fatal(err)
	}

	q = reopen(t, dir)
	defer q.Close()
	if got, ok := q.Query("small"); !ok || got.Payload != small.Message.Payload {
		t.Fatalf("small payload lost across auto compaction: ok=%v %x", ok, got.Payload)
	}
	got, ok := q.Query("filler")
	if !ok {
		t.Fatal("filler missing after auto compaction and reopen")
	}
	if got.Payload != filler.Message.Payload {
		t.Fatalf("filler payload changed across auto compaction:\nwant len=%d\ngot  len=%d",
