		"both payload and payloadB64": {
			T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1,
			Payload: "x", PayloadB64: "eA==", ProofAt: 10,
		},
		"undecodable payloadB64": {
			T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1,
			PayloadB64: "!!!not-base64!!!", ProofAt: 10,
