1	package relayproof
2	
3	import (
4		"errors"
5		"os"
6		"path/filepath"
7		"strconv"
8		"strings"
9		"testing"
10	)
11	
12	// Regression coverage for AUTOMATIC log compaction triggered by an ordinary
13	// successful Submit crossing the 4 MiB threshold — not a manually invoked
14	// store.compact. When that submit returns success, the triggering message
15	// must already be part of the compacted state together with every earlier
16	// message, and compaction must have no business effect:
17	//
18	//   - earlier records stay individually queryable with every content field
19	//     (id, source chain, destination chain, nonce, payload, proof height and
20	//     expiry) at its original value, and the listing appends the new record
21	//     at the end in first-submission order, each id appearing exactly once;
22	//   - the triggering message stays pending with zero attempts and no retry
23	//     time: compaction itself never processes it and never changes earlier
24	//     statuses or reasons;
25	//   - close/reopen of the same state directory restores the same content and
26	//     order — the last submit must not exist only before closing;
27	//   - continued delivery keeps first-submission order for two messages
28	//     sharing one (source, destination, nonce): the first succeeds, the
29	//     second ends replay whose reason names the first; the submit that
30	//     triggered compaction gets no extra priority;
31	//   - the post-compaction submission boundary is unchanged: an identical
32	//     resubmit returns the existing record without adding an entry, while a
33	//     resubmit with different content is ErrConflict and leaves the original
34	//     record, the seq assignment and the processing order untouched.
35	//
36	// Crossing the threshold honestly but cheaply: equal-time advance
37	// checkpoints are small frames that are legal to repeat while no message
38	// exists yet, and every checkpoint but the last is excluded from a compaction
39	// snapshot, so a few hundred of them pad the active log up to the boundary
40	// with a handful of fsyncs. A large PRIOR filler supplies the retained bulk,
41	// and the ordinary small submit at the end crosses by a few dozen bytes; the
42	// snapshot then genuinely shrinks well below 4 MiB. All frame sizes are
43	// measured against real framed records rather than hard-coded.
44	
45	// gaugeFrames opens a throwaway queue with the same source/header setup and
46	// returns: the log size right after the source+header pair, the framed size
47	// of one equal-time advance checkpoint, and the framed submit size of each
48	// envelope in order. A throwaway record occupies seq 0 first, so the gauged
49	// envelopes carry seqs 1..N exactly as they do in the real queue (a seq-0
50	// submit is JSON-omitted and would otherwise be measured 8 bytes short).
51	// Envelopes must be ASCII-payload.
52	func gaugeFrames(t *testing.T, envs []Envelope) (base, checkpoint int64, frames []int64) {
53		t.Helper()
54		q, _ := openTempQueue(t)
55		defer q.Close()
56		if err := q.RegisterSource("a"); err != nil {
57			t.Fatal(err)
58		}
59		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
60			t.Fatal(err)
61		}
62		base = q.store.size
63		if _, err := q.Advance(1000); err != nil {
64			t.Fatal(err)
65		}
66		checkpoint = q.store.size - base
67		if _, err := q.Submit(Envelope{Message: Message{
68			ID: "gauge-seq0", From: "a", To: "b", Nonce: 999_999,
69			Payload: "seq-zero-placeholder", ProofAt: 1,
